pub fn binary_search(nums: &[i32], target: i32) -> i32 {
    let mut lo = 0usize;
    let mut hi = nums.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if nums[mid] == target {
            return mid as i32;
        }
        if nums[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    -1
}

pub fn dfs(graph: &[Vec<usize>], start: usize, mut visit: impl FnMut(usize)) {
    let mut stack = vec![start];
    let mut seen = vec![false; graph.len()];
    while let Some(node) = stack.pop() {
        if seen[node] {
            continue;
        }
        seen[node] = true;
        visit(node);
        for &next in graph[node].iter().rev() {
            if !seen[next] {
                stack.push(next);
            }
        }
    }
}

use std::collections::VecDeque;

pub fn bfs(graph: &[Vec<usize>], start: usize, mut visit: impl FnMut(usize)) {
    let mut queue = VecDeque::from([start]);
    let mut seen = vec![false; graph.len()];
    seen[start] = true;
    while let Some(node) = queue.pop_front() {
        visit(node);
        for &next in &graph[node] {
            if !seen[next] {
                seen[next] = true;
                queue.push_back(next);
            }
        }
    }
}

pub fn two_sum_sorted(nums: &[i32], target: i32) -> (usize, usize) {
    let mut left = 0usize;
    let mut right = nums.len().saturating_sub(1);
    while left < right {
        let sum = nums[left] + nums[right];
        if sum == target {
            return (left, right);
        }
        if sum < target {
            left += 1;
        } else {
            right -= 1;
        }
    }
    (0, 0)
}

pub fn is_valid_parentheses(input: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    for ch in input.chars() {
        match ch {
            '(' | '[' | '{' => stack.push(ch),
            ')' => {
                if stack.pop() != Some('(') {
                    return false;
                }
            }
            ']' => {
                if stack.pop() != Some('[') {
                    return false;
                }
            }
            '}' => {
                if stack.pop() != Some('{') {
                    return false;
                }
            }
            _ => {}
        }
    }
    stack.is_empty()
}

pub fn climb_stairs(n: usize) -> u64 {
    if n <= 2 {
        return n as u64;
    }
    let mut prev = 1u64;
    let mut curr = 2u64;
    for _ in 3..=n {
        let next = prev + curr;
        prev = curr;
        curr = next;
    }
    curr
}

pub fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0usize, 0usize);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

pub fn quickselect(nums: &mut [i32], k: usize) -> i32 {
    let (mut left, mut right) = (0usize, nums.len() - 1);
    loop {
        let pivot = nums[right];
        let mut store = left;
        for i in left..right {
            if nums[i] < pivot {
                nums.swap(i, store);
                store += 1;
            }
        }
        nums.swap(store, right);
        if store == k {
            return nums[store];
        }
        if k < store {
            right = store - 1;
        } else {
            left = store + 1;
        }
    }
}
